(("undefined"!=typeof globalThis?globalThis:self)["makoChunk_@ant-design/x"]=("undefined"!=typeof globalThis?globalThis:self)["makoChunk_@ant-design/x"]||[]).push([["9ff1d4aa"],{"9ff1d4aa":function(e,a,n){"use strict";n.d(a,"__esModule",{value:!0}),n.d(a,"texts",{enumerable:!0,get:function(){return t;}}),n("7015eb76");let t=[{value:"The ",paraId:0},{value:"components",paraId:0},{value:" property is the primary extension point in ",paraId:0},{value:"@ant-design/x-markdown",paraId:0},{value:". It lets you map Markdown/HTML nodes to your own React components so you can control rendering, streaming behavior, and business data interaction in one place. To extend further, see ",paraId:0},{value:"Plugins",paraId:1},{value:" and custom renderers.",paraId:0},{value:"import React from 'react';\nimport { Mermaid, Think, XMarkdown } from '@ant-design/x';\n\n<XMarkdown\n  components={{\n    think: Think,\n    mermaid: Mermaid,\n  }}\n/>;\n",paraId:2,tocIndex:0},{value:"Property",paraId:3,tocIndex:1},{value:"Description",paraId:3,tocIndex:1},{value:"Type",paraId:3,tocIndex:1},{value:"Default",paraId:3,tocIndex:1},{value:"domNode",paraId:3,tocIndex:1},{value:"Component DOM node from html-react-parser, containing parsed DOM node information",paraId:3,tocIndex:1},{value:"DOMNode",paraId:3,tocIndex:1},{value:"-",paraId:3,tocIndex:1},{value:"streamStatus",paraId:3,tocIndex:1},{value:"Streaming rendering supports two states: ",paraId:3,tocIndex:1},{value:"loading",paraId:3,tocIndex:1},{value:" indicates content is being loaded, ",paraId:3,tocIndex:1},{value:"done",paraId:3,tocIndex:1},{value:" indicates loading is complete. Currently only supports HTML format and fenced code blocks. Since indented code has no clear end marker, it always returns ",paraId:3,tocIndex:1},{value:"done",paraId:3,tocIndex:1},{value:" status",paraId:3,tocIndex:1},{value:"'loading' | 'done'",paraId:3,tocIndex:1},{value:"-",paraId:3,tocIndex:1},{value:"children",paraId:3,tocIndex:1},{value:"Content wrapped in the component, containing the text content of DOM nodes",paraId:3,tocIndex:1},{value:"React.ReactNode",paraId:3,tocIndex:1},{value:"-",paraId:3,tocIndex:1},{value:"rest",paraId:3,tocIndex:1},{value:"Component properties, supports all standard HTML attributes (such as ",paraId:3,tocIndex:1},{value:"href",paraId:3,tocIndex:1},{value:", ",paraId:3,tocIndex:1},{value:"title",paraId:3,tocIndex:1},{value:", ",paraId:3,tocIndex:1},{value:"className",paraId:3,tocIndex:1},{value:", etc.) and custom data attributes",paraId:3,tocIndex:1},{value:"Record<string, any>",paraId:3,tocIndex:1},{value:"-",paraId:3,tocIndex:1},{value:"Custom components often need business data (theme, callbacks, etc.). Passing it via an inline function creates a new component reference on every render, so React unmounts and remounts the whole subtree \u2014 losing internal state and hurting performance in streaming scenarios. Use ",paraId:4,tocIndex:2},{value:"componentsProps",paraId:4,tocIndex:2},{value:" to pass extra props while keeping component references stable:",paraId:4,tocIndex:2},{value:"import React, { useMemo } from 'react';\nimport { XMarkdown } from '@ant-design/x';\n\n// \u274C Inline function: a new component type every render, the subtree is rebuilt\n<XMarkdown\n  components={{\n    'custom-chart': (props) => <CustomChart {...props} theme={theme} onSelect={onSelect} />,\n  }}\n/>;\n\n// \u2705 Stable component reference; extra data flows through componentsProps\nconst components = { 'custom-chart': CustomChart };\nconst componentsProps = useMemo(() => ({ 'custom-chart': { theme, onSelect } }), [theme, onSelect]);\n\n<XMarkdown components={components} componentsProps={componentsProps} />;\n",paraId:5,tocIndex:2},{value:"componentsProps",paraId:6,tocIndex:2},{value:" is keyed by tag name. Its props are merged with the parsed HTML attributes and passed to the component:",paraId:6,tocIndex:2},{value:"On conflict ",paraId:7,tocIndex:2},{value:"componentsProps",paraId:7,tocIndex:2},{value:" wins \u2014 a ",paraId:7,tocIndex:2},{value:"title",paraId:7,tocIndex:2},{value:" in ",paraId:7,tocIndex:2},{value:"componentsProps",paraId:7,tocIndex:2},{value:" overrides ",paraId:7,tocIndex:2},{value:'title="..."',paraId:7,tocIndex:2},{value:" from the HTML.",paraId:7,tocIndex:2},{value:"className",paraId:7,tocIndex:2},{value:" / ",paraId:7,tocIndex:2},{value:"class",paraId:7,tocIndex:2},{value:" is the exception: both sides are concatenated, with the ",paraId:7,tocIndex:2},{value:"componentsProps",paraId:7,tocIndex:2},{value:" class name first.",paraId:7,tocIndex:2},{value:"Internally computed props \u2014 ",paraId:7,tocIndex:2},{value:"domNode",paraId:7,tocIndex:2},{value:", ",paraId:7,tocIndex:2},{value:"streamStatus",paraId:7,tocIndex:2},{value:", ",paraId:7,tocIndex:2},{value:"children",paraId:7,tocIndex:2},{value:" (plus ",paraId:7,tocIndex:2},{value:"lang",paraId:7,tocIndex:2},{value:" and ",paraId:7,tocIndex:2},{value:"block",paraId:7,tocIndex:2},{value:" for ",paraId:7,tocIndex:2},{value:"code",paraId:7,tocIndex:2},{value:") \u2014 cannot be overridden and are ignored if present in ",paraId:7,tocIndex:2},{value:"componentsProps",paraId:7,tocIndex:2},{value:".",paraId:7,tocIndex:2},{value:"When ",paraId:8,tocIndex:2},{value:"componentsProps",paraId:8,tocIndex:2},{value:" changes, the component receives a normal props update without being remounted. Like ",paraId:8,tocIndex:2},{value:"components",paraId:8,tocIndex:2},{value:", it takes part in the render cache, so ",paraId:8,tocIndex:2},{value:"passing an inline object literal invalidates that cache on every render and re-parses the whole tree",paraId:8,tocIndex:2},{value:" \u2014 keep the reference stable with ",paraId:8,tocIndex:2},{value:"useMemo",paraId:8,tocIndex:2},{value:" as shown above.",paraId:8,tocIndex:2},{value:"Keep component references stable. Avoid inline function components in ",paraId:9,tocIndex:3},{value:"components",paraId:9,tocIndex:3},{value:"; use ",paraId:9,tocIndex:3},{value:"componentsProps",paraId:9,tocIndex:3},{value:" to pass extra data.",paraId:9,tocIndex:3},{value:"Use ",paraId:9,tocIndex:3},{value:"streamStatus",paraId:9,tocIndex:3},{value:" to separate loading UI (",paraId:9,tocIndex:3},{value:"loading",paraId:9,tocIndex:3},{value:") from finalized UI (",paraId:9,tocIndex:3},{value:"done",paraId:9,tocIndex:3},{value:").",paraId:9,tocIndex:3},{value:"If data depends on complete syntax, fetch or parse after ",paraId:9,tocIndex:3},{value:"streamStatus === 'done'",paraId:9,tocIndex:3},{value:".",paraId:9,tocIndex:3},{value:"Keep custom tags semantically clear and avoid ambiguous mixed Markdown/HTML blocks.",paraId:9,tocIndex:3},{value:"If block-level custom tags contain unexpected blank lines, Markdown parsers may end the HTML block early and convert trailing content into paragraphs. To avoid this:",paraId:10,tocIndex:4},{value:"Keep content inside custom tags contiguous when possible.",paraId:11,tocIndex:4},{value:"Or place blank lines both before and after the full custom block so the parser treats it as an independent block.",paraId:11,tocIndex:4}];}}]);